template.query:
query SystemStatisticsFull {
  systemStats {
    memory {
      used
      free
      total
      percentage
      heap {
        used
        total
        external
        arrayBuffers
      }
    }
    process {
      pid
      cpu
      version
      platform
    }
    database {
      connectionCount
      queryCount
      averageQueryTime
    }
    timestamp
    uptime
  }
}
